Develop a function that takes a binary tree and calculates the sum of all left leaves. A left leaf is defined as a node that is a leaf (it has no children) and is the left child of its parent. You need to design a BinaryTree class with an insert method to create the tree, and then a method to calculate the sum of left leaves. Consider edge cases such as a tree with only one node or no left leaves.

```python
class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinaryTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, current, value):
        if value < current.value:
            if current.left is None:
                current.left = Node(value)
            else:
                self._insert_recursive(current.left, value)
        else:
            if current.right is None:
                current.right = Node(value)
            else:
                self._insert_recursive(current.right, value)

    def sum_of_left_leaves(self):
        def _sum_of_left_leaves(node, is_left):
            if node is None:
                return 0
            if is_left and node.left is None and node.right is None:
                return node.value
            return _sum_of_left_leaves(node.left, True) + _sum_of_left_leaves(node.right, False)

        return _sum_of_left_leaves(self.root, False)

# Example usage:
# Construct the binary tree
bt = BinaryTree()
bt.insert(7)
bt.insert(5)
bt.insert(10)
bt.insert(3)
bt.insert(6)
bt.insert(8)
bt.insert(12)

# Calculate the sum of left leaves
print(bt.sum_of_left_leaves())  # Output should be the sum of values of left leaves nodes
