using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class FireBall : MonoBehaviour
{
    public Transform player;
    public LayerMask platformLayer;
    public float speed = 5f;
    private Rigidbody2D rb2d;
    private new Collider2D collider;
    private bool grounded;

    private void Awake()
    {
        rb2d = GetComponent<Rigidbody2D>();
        collider = GetComponent<Collider2D>();
    }

    private void CheckGrounded()
    {
        Bounds bounds = collider.bounds;
        Vector2 size = new Vector2(bounds.size.x, 0.1f);
        Vector2 center = new Vector2(bounds.center.x, bounds.min.y);

        Collider2D[] colliders = Physics2D.OverlapBoxAll(center, size, 0f, platformLayer);

        grounded = colliders.Length > 0;
    }

    void Update()
    {
        // Check if player exists
        if (player == null)
        {
            // If player is not found, do something (e.g., destroy the fireball)
            Destroy(gameObject);
            return;
        }

        // Calculate direction towards the player
        Vector3 direction = player.position - transform.position;
        direction.Normalize();

        // Move the fireball only horizontally on the platform
        if (grounded)
        {
            rb2d.velocity = new Vector2(direction.x * speed, rb2d.velocity.y);
        }

        // Check if fireball is grounded
        CheckGrounded();

        // Rotate the fireball to face the player, only on the x and y axes
        Quaternion targetRotation = Quaternion.LookRotation(direction, Vector3.up);
        transform.rotation = Quaternion.Euler(new Vector3(0f, 0f, 0f));
    }
}
