import time
import queue
import threading

class TaskScheduler:
    """ A multithreaded task scheduler that uses different types of queues (FIFO, LIFO, Priority) to manage tasks.

    >>> scheduler = TaskScheduler('FIFO')
    >>> scheduler.add_task(1, 0.1)
    >>> scheduler.add_task(2, 0.2)
    >>> scheduler.start_workers(1)
    >>> scheduler.join()

    >>> scheduler = TaskScheduler('LIFO')
    >>> scheduler.add_task(1, 0.1)
    >>> scheduler.add_task(2, 0.2)
    >>> scheduler.start_workers(1)
    >>> scheduler.join()

    >>> scheduler = TaskScheduler('Priority')
    >>> scheduler.add_task(1, 0.2, priority=2)
    >>> scheduler.add_task(2, 0.1, priority=1)
    >>> scheduler.start_workers(1)
    >>> scheduler.join()
    """

    def __init__(self, queue_type: str):
        if queue_type == 'FIFO':
            self.queue = queue.Queue()
        elif queue_type == 'LIFO':
            self.queue = queue.LifoQueue()
        elif queue_type == 'Priority':
            self.queue = queue.PriorityQueue()
        else:
            raise ValueError('Invalid queue type')

    def add_task(self, task_id: int, processing_time: float, priority: int = 0):
        if isinstance(self.queue, queue.PriorityQueue):
            self.queue.put((priority, (task_id, processing_time)))
        else:
            self.queue.put((task_id, processing_time))

    def start_workers(self, num_workers: int):
        def worker():
            while True:
                task = self.queue.get()
                if isinstance(self.queue, queue.PriorityQueue):
                    _, (task_id, processing_time) = task
                else:
                    task_id, processing_time = task
                print(f'Starting task {task_id}')
                time.sleep(processing_time)
                print(f'Completed task {task_id}')
                self.queue.task_done()

        for _ in range(num_workers):
            threading.Thread(target=worker, daemon=True).start()

    def join(self):
        self.queue.join()

import plistlib

def load_plist(file_path, fmt=None):
    """
    Read a property list file from a given file path and return the content as a dictionary.

    :param file_path: Path to the plist file to read.
    :param fmt: Format of the plist file. Default is None (autodetect format).
    :return: Dictionary containing the content of the plist file.
    """
    try:
        with open(file_path, 'rb') as f:
            if fmt is None:
                return plistlib.load(f)
            elif fmt == 'FMT_XML':
                return plistlib.load(f, fmt=plistlib.FMT_XML)
            elif fmt == 'FMT_BINARY':
                return plistlib.load(f, fmt=plistlib.FMT_BINARY)
            else:
                raise ValueError("Unsupported format specified")
    except FileNotFoundError:
        raise
    except plistlib.InvalidFileException:
        raise

def save_plist(data, file_path, fmt='FMT_XML', sort_keys=True, skipkeys=False):
    """
    Write a given dictionary to a specified file path in either XML or binary format.

    :param data: Dictionary to save as a plist file.
    :param file_path: Path to save the plist file.
    :param fmt: Format of the plist file ('FMT_XML' or 'FMT_BINARY'). Default is 'FMT_XML'.
    :param sort_keys: Whether to sort the dictionary keys. Default is True.
    :param skipkeys: Whether to skip non-string keys in dictionaries. Default is False.
    :return: None
    """
    try:
        with open(file_path, 'wb') as f:
            if fmt == 'FMT_XML':
                plistlib.dump(data, f, fmt=plistlib.FMT_XML, sort_keys=sort_keys, skipkeys=skipkeys)
            elif fmt == 'FMT_BINARY':
                plistlib.dump(data, f, fmt=plistlib.FMT_BINARY, sort_keys=sort_keys, skipkeys=skipkeys)
            else:
                raise ValueError("Unsupported format specified")
    except TypeError:
        raise
    except OverflowError:
        raise

def convert_plist(src_file_path, dest_file_path, dest_fmt):
    """
    Convert an XML-formatted plist file to a binary-formatted plist file.

